import React, { useEffect, useRef, useCallback, useState } from 'react';
import './FluidSimulation.css';

const FluidSimulation = () => {
  const canvasRef = useRef(null);
  const animationRef = useRef(null);
  const mousePositionRef = useRef({ x: 0, y: 0 });
  const particlesRef = useRef([]);

  // Fluid parameters
  const CANVAS_WIDTH = 800;
  const CANVAS_HEIGHT = 600;
  const PARTICLE_COUNT = 150;
  const MOUSE_INFLUENCE_RADIUS = 120;
  const VISCOSITY = 0.98;
  const MOUSE_FORCE = 0.3;

  // Initialize fluid particles
  const initializeParticles = useCallback(() => {
    const particles = [];
    for (let i = 0; i < PARTICLE_COUNT; i++) {
      particles.push({
        x: Math.random() * CANVAS_WIDTH,
        y: Math.random() * CANVAS_HEIGHT,
        vx: 0,
        vy: 0,
        originalX: Math.random() * CANVAS_WIDTH,
        originalY: Math.random() * CANVAS_HEIGHT,
        hue: Math.random() * 60 + 180, // Blue to cyan range
        opacity: Math.random() * 0.8 + 0.2
      });
    }
    particlesRef.current = particles;
  }, []);

  // Mouse event handlers
  const handleMouseMove = (e) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const scaleX = CANVAS_WIDTH / rect.width;
    const scaleY = CANVAS_HEIGHT / rect.height;

    mousePositionRef.current = {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY
    };
  };

  // Update particle positions based on mouse influence
  const updateParticles = () => {
    const mouse = mousePositionRef.current;
    const particles = particlesRef.current;

    particles.forEach(particle => {
      // Calculate distance to mouse
      const dx = mouse.x - particle.x;
      const dy = mouse.y - particle.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      // Apply mouse influence if within radius
      if (distance < MOUSE_INFLUENCE_RADIUS && distance > 0) {
        const force = (MOUSE_INFLUENCE_RADIUS - distance) / MOUSE_INFLUENCE_RADIUS;
        const normalizedDx = dx / distance;
        const normalizedDy = dy / distance;

        // Create fluid-like displacement
        particle.vx += normalizedDx * force * MOUSE_FORCE;
        particle.vy += normalizedDy * force * MOUSE_FORCE;
      }

      // Add subtle return-to-origin force
      const returnDx = particle.originalX - particle.x;
      const returnDy = particle.originalY - particle.y;
      particle.vx += returnDx * 0.002;
      particle.vy += returnDy * 0.002;

      // Apply viscosity (damping)
      particle.vx *= VISCOSITY;
      particle.vy *= VISCOSITY;

      // Update position
      particle.x += particle.vx;
      particle.y += particle.vy;

      // Boundary conditions - wrap around edges
      if (particle.x < 0) particle.x = CANVAS_WIDTH;
      if (particle.x > CANVAS_WIDTH) particle.x = 0;
      if (particle.y < 0) particle.y = CANVAS_HEIGHT;
      if (particle.y > CANVAS_HEIGHT) particle.y = 0;
    });
  };

  // Render the fluid simulation
  const render = () => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    // Clear canvas with fade effect
    ctx.fillStyle = 'rgba(10, 15, 35, 0.1)';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const particles = particlesRef.current;
    const mouse = mousePositionRef.current;

    // Draw connecting lines between nearby particles
    ctx.globalCompositeOperation = 'lighter';

    for (let i = 0; i < particles.length; i++) {
      for (let j = i + 1; j < particles.length; j++) {
        const dx = particles[i].x - particles[j].x;
        const dy = particles[i].y - particles[j].y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < 80) {
          const opacity = (80 - distance) / 80 * 0.3;
          ctx.strokeStyle = `hsla(${particles[i].hue}, 70%, 60%, ${opacity})`;
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(particles[i].x, particles[i].y);
          ctx.lineTo(particles[j].x, particles[j].y);
          ctx.stroke();
        }
      }
    }

    // Draw particles
    particles.forEach(particle => {
      // Calculate distance to mouse for glow effect
      const dx = mouse.x - particle.x;
      const dy = mouse.y - particle.y;
      const distanceToMouse = Math.sqrt(dx * dx + dy * dy);

      let glowRadius = 3;
      let glowOpacity = particle.opacity;

      // Enhance particles near mouse
      if (distanceToMouse < MOUSE_INFLUENCE_RADIUS) {
        const proximity = 1 - (distanceToMouse / MOUSE_INFLUENCE_RADIUS);
        glowRadius = 3 + proximity * 8;
        glowOpacity = particle.opacity + proximity * 0.5;
      }

      // Create gradient for particle glow
      const gradient = ctx.createRadialGradient(
        particle.x, particle.y, 0,
        particle.x, particle.y, glowRadius
      );
      gradient.addColorStop(0, `hsla(${particle.hue}, 80%, 70%, ${glowOpacity})`);
      gradient.addColorStop(0.5, `hsla(${particle.hue}, 70%, 50%, ${glowOpacity * 0.3})`);
      gradient.addColorStop(1, `hsla(${particle.hue}, 60%, 30%, 0)`);

      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, glowRadius, 0, Math.PI * 2);
      ctx.fill();
    });

    // Draw subtle mouse influence area
    if (mouse.x && mouse.y) {
      const gradient = ctx.createRadialGradient(
        mouse.x, mouse.y, 0,
        mouse.x, mouse.y, MOUSE_INFLUENCE_RADIUS
      );
      gradient.addColorStop(0, 'rgba(255, 255, 255, 0.02)');
      gradient.addColorStop(0.7, 'rgba(100, 200, 255, 0.01)');
      gradient.addColorStop(1, 'rgba(100, 200, 255, 0)');

      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(mouse.x, mouse.y, MOUSE_INFLUENCE_RADIUS, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.globalCompositeOperation = 'source-over';
  };

  // Animation loop
  const animate = useCallback(() => {
    updateParticles();
    render();
    animationRef.current = requestAnimationFrame(animate);
  }, []);

  // Initialize simulation when component mounts
  useEffect(() => {
    initializeParticles();
    animate();

    // Cleanup animation on unmount
    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [animate, initializeParticles]);

  // Reset simulation
  const resetSimulation = () => {
    initializeParticles();
  };

  return (
    <div className="fluid-simulation">
      {/* Left Panel - Simulation */}
      <div className="simulation-container">
        <div className="simulation-header">
          <h1 className="simulation-title">Fluid Simulation</h1>
          <div className="simulation-status">
            <div className="status-dot"></div>
            <span>Active</span>
          </div>
        </div>
        <div className="canvas-wrapper">
          <canvas
            ref={canvasRef}
            width={CANVAS_WIDTH}
            height={CANVAS_HEIGHT}
            className="simulation-canvas fluid-canvas"
            onMouseMove={handleMouseMove}
          />
        </div>
      </div>

      {/* Right Panel - Controls */}
      <div className="controls">
        <div className="control-panel">
          <h3 className="control-title">
            <div className="control-icon">🌊</div>
            Fluid Controls
          </h3>
          <div className="fluid-controls">
            <button onClick={resetSimulation} className="reset-button">
              🔄 Reset Fluid
            </button>
          </div>
        </div>

        <div className="control-panel info">
          <h3 className="info-title">
            <div className="control-icon">ℹ️</div>
            Fluid Info
          </h3>
          <p><strong>Interactive Fluid:</strong> {PARTICLE_COUNT} particles forming a dynamic fluid-like system.</p>
          <p><strong>Mouse Influence:</strong> Move your mouse to disturb the fluid and create beautiful flow patterns.</p>
          <p><strong>Viscosity:</strong> Particles slowly return to their original positions with realistic damping.</p>
          <p><strong>Visual Effects:</strong> Glowing particles with connecting threads create an immersive fluid experience.</p>
        </div>
      </div>
    </div>
  );
};

export default FluidSimulation;
